import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, vec2, float, uniform, hash, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, SRGBColorSpace, DoubleSide } = ctx.THREE;

  const group = new Group();
  group.name = 'hub-features-card-1';

  // Spec palette
  const inkHex = '#16161d';
  const paperHex = '#e8ecf2';
  const accentHex = '#ff2a38';
  const surfaceHex = '#0b0b10';

  const ink = vec3(Color(inkHex));
  const surface = vec3(Color(surfaceHex));
  const accent = vec3(Color(accentHex));

  // Card dimensions matching 512x320 atlas (16:10)
  const cardW = 2.4;
  const cardH = 1.5;

  // ---- Main card plane (textured) ----
  const planeGeo = new PlaneGeometry(cardW, cardH);
  const mat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });

  const texUniform = uniform(null);

  // Fallback engineered gradient surface until texture arrives
  const uvNode = uv();
  const fallbackGrad = mix(surface, ink, uvNode.y);
  mat.colorNode = fallbackGrad;

  const cardMesh = new Mesh(planeGeo, mat);
  cardMesh.name = 'feature-card-1-mesh';
  group.add(cardMesh);

  // ---- Backdrop staging plane (dark, behind card) ----
  const backGeo = new PlaneGeometry(cardW * 1.18, cardH * 1.22);
  const backMat = new MeshBasicNodeMaterial({ transparent: true });
  const backGrad = mix(vec3(Color('#06060a')), vec3(Color('#101018')), uvNode.y);
  backMat.colorNode = backGrad.mul(float(0.85));
  const backMesh = new Mesh(backGeo, backMat);
  backMesh.position.z = -0.08;
  backMesh.name = 'feature-card-1-backdrop';
  group.add(backMesh);

  // ---- Accent signal bar (<=10% of frame) ----
  const barGeo = new PlaneGeometry(cardW * 0.92, 0.04);
  const barMat = new MeshBasicNodeMaterial({ transparent: true });
  barMat.colorNode = accent.mul(float(1.6));
  const barMesh = new Mesh(barGeo, barMat);
  barMesh.position.set(0, -cardH * 0.5 + 0.08, 0.01);
  barMesh.name = 'feature-card-1-accent';
  group.add(barMesh);

  // ---- Load card texture and rebuild color node ----
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = SRGBColorSpace;
    tex.needsUpdate = true;
    texUniform.value = tex;

    const texSample = texture(texUniform, uvNode);

    // Subtle static grain
    const grainSeed = uvNode.mul(vec2(1024.0, 640.0)).add(vec2(7.31, 13.17));
    const grain = hash(grainSeed).sub(float(0.5)).mul(float(0.035));

    // Engineered gradient overlay: slight darkening at top edge for depth
    const topFade = mix(float(0.0), float(0.18), float(1.0).sub(uvNode.y).pow(float(2.2)));
    const bottomLift = mix(float(0.0), float(0.06), uvNode.y.pow(float(2.0)));

    const baseRGB = texSample.rgb.add(grain);
    const graded = baseRGB.sub(topFade).add(bottomLift);

    mat.colorNode = graded;
    mat.needsUpdate = true;
  }).catch(() => {});

  // ---- Entrance animation (weighted-settle) ----
  cardMesh.scale.set(0.96, 0.96, 0.96);
  cardMesh.position.z = -0.15;
  mat.opacity = 0;

  const tl = gsap.timeline();
  tl.to(mat, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  tl.to(cardMesh.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.7, ease: 'power3.out' }, 0);
  tl.to(cardMesh.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.5, ease: 'power4.out' }, 0.7);
  tl.to(cardMesh.position, { z: 0, duration: 0.7, ease: 'power3.out' }, 0);

  // Accent bar draw-in
  barMesh.scale.x = 0.001;
  tl.to(barMesh.scale, { x: 1.0, duration: 0.6, ease: 'power3.out' }, 0.45);

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    tl.kill();
    planeGeo.dispose();
    backGeo.dispose();
    barGeo.dispose();
    mat.dispose();
    backMat.dispose();
    barMat.dispose();
    const t = texUniform.value;
    if (t && t.dispose) t.dispose();
  };

  return group;
}
